<section class="section-title"><div><h1><?= e($conversation['subject'] ?? 'گفتگوی پشتیبانی') ?></h1><p class="muted"><?= e(fa_label($conversation['category'] ?? 'technical_support')) ?> · <span class="pill"><?= e(fa_label($conversation['status'] ?? 'open')) ?></span></p></div><a class="button secondary" href="/support">بازگشت</a></section>
<section class="card chat-thread"><?php foreach (($messages ?? []) as $m): ?><article class="message <?= !empty($m['is_internal_note']) ? 'caution' : '' ?>"><p class="message-body"><?= nl2br(e($m['body'])) ?></p><small><?= e(trim(($m['first_name'] ?? '').' '.($m['last_name'] ?? ''))) ?> · <?= e($m['created_at']) ?><?= !empty($m['is_internal_note']) ? ' · یادداشت داخلی' : '' ?></small></article><?php endforeach; ?><?php if (empty($messages)): ?><p class="muted">هنوز پیامی ثبت نشده است.</p><?php endif; ?></section>
<section class="card composer-card"><form method="post" action="/support/<?= (int)($conversation['id'] ?? 0) ?>/messages"><?= csrf_field() ?><label>پیام<textarea name="body" rows="3" maxlength="3000" required></textarea></label><?php if (($user['role_name'] ?? '') === 'admin'): ?><label class="check"><input type="checkbox" name="internal_note" value="1"> یادداشت داخلی مدیران</label><?php endif; ?><button class="button">ارسال</button></form></section>
